// Generated by vibelang from src/features/runs/source.vibe; the migrate flow writes it again with each batch.
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Stream from "effect/Stream";
import { ShapeSource } from "@smthrs/effect-electric";
/** Repository flow runs require a Member, including on a public repository. No authority means no request. */
export const memberRunSource = (source, auth, repos, id) => ShapeSource.gated(source, Option.isNone(auth) || Option.isNone(repos)
    ? Stream.succeed(false)
    : Stream.zipLatestWith(auth.value.sessionState.rows, repos.value.rolesState.rows, (sessions, roles) => {
        const session = sessions[0];
        const row = roles.find((role) => role.id === id);
        const role = row?.own ? session.role : row?.role;
        return session.status === "signed_in" && row?.synced !== false
            && (role === "member" || role === "maintainer" || role === "admin");
    }).pipe(Stream.changes));
/** `read` once sign-in resolves to signed in, else `visitor`: a visitor's authenticated read would only log a 401. */
export const whenSignedIn = (read, visitor, auth) => Option.isNone(auth)
    ? read
    : auth.value.sessionState.rows.pipe(Stream.filter((rows) => rows[0].status === "signed_in" || rows[0].status === "signed_out"), Stream.runHead, Effect.flatMap((rows) => Option.isSome(rows) && rows.value[0].status === "signed_in" ? read : visitor));
/** Wait for sign-in to resolve before reading the authenticated cloud index. */
export const cloudRunList = (read, auth) => whenSignedIn(read, Effect.succeed([]), auth);
